\u0430: c \u2208 {0.6, 0.7, 0.8, 0.85, 0.9, 0.95, 1.0 (=\u0431\u0435\u0437 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433\u0430, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c), 1.05, 1.1, 1.2}. \u0414\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u044f\u044f \u0441\u0435\u0442\u043a\u0430 \u043d\u0443\u0436\u043d\u0430, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u0439\u043c\u0430\u0442\u044c \u043e\u043f\u0442\u0438\u043c\u0443\u043c \u0441 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u043e\u0440\u043e\u043d \u043e\u0442 1.0: \u0430\u0433\u0440\u0435\u0441\u0441\u0438\u0432\u043d\u044b\u0439 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433 \u0440\u0435\u0436\u0435\u0442 \u0432\u044b\u0431\u0440\u043e\u0441\u044b (\u043c\u0435\u043d\u044c\u0448\u0435 \u043e\u0448\u0438\u0431\u043a\u0430 \u0448\u0430\u0433\u0430 \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f), \u043d\u043e \u0438\u0441\u043a\u0430\u0436\u0430\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f.\n\n**\u0413\u0434\u0435 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0442\u044c \u2014 \u0444\u0430\u043a\u0442\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d 3 \u0443\u0440\u043e\u0432\u043d\u044f \"\u043b\u043e\u043a\u0443\u0441\u0430\" \u00d7 \u0441\u0435\u0442\u043a\u0430 c:**\n- A: \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433 \u0442\u043e\u043b\u044c\u043a\u043e inputs (\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u043e\u0435 \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u0435 \u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0439);\n- B: \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433 \u0442\u043e\u043b\u044c\u043a\u043e KV cache (\u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u043e\u0435);\n- C: \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433 \u043e\u0431\u0430 (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 c \u0434\u043b\u044f \u043e\u0431\u043e\u0438\u0445) \u2014 \u044d\u0442\u043e \u0438 \u0435\u0441\u0442\u044c \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 \u0432\u043e\u043f\u0440\u043e\u0441\u0430.\n\u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u044c \u0432\u043a\u043b\u0430\u0434 \u0432\u0445\u043e\u0434\u043e\u0432 \u0438 KV-\u043a\u044d\u0448\u0430 \u0438 \u043d\u0430\u0439\u0442\u0438 \u043e\u043f\u0442\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 c \u0438\u043c\u0435\u043d\u043d\u043e \u0434\u043b\u044f \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044f C.\n\n**\u0424\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 (\u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0442\u043e\u0447\u0435\u043a \u0441\u0435\u0442\u043a\u0438):**\n- \u043c\u043e\u0434\u0435\u043b\u044c LLAMA2-7B, \u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u0447\u0435\u043a\u043f\u043e\u0438\u043d\u0442-\u0432\u0435\u0440\u0441\u0438\u044f;\n- \u0431\u0438\u0442\u043d\u043e\u0441\u0442\u0438 \u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0439 \u0438 KV-\u043a\u044d\u0448\u0430 (\u0438\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430; \u0435\u0441\u043b\u0438 \u0442\u0430\u043c \u043d\u0435\u0442 \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435, \u0441\u043c. \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f);\n- \u0433\u0440\u0430\u043d\u0443\u043b\u044f\u0440\u043d\u043e\u0441\u0442\u044c \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f (per-token/per-channel \u0438\u043b\u0438 per-group), \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u0432\u0445\u043e\u0434\u043e\u0432 / \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f KV \u2014 \u043a\u0430\u043a \u0432 \u0441\u0435\u0442\u0430\u043f\u0435;\n- \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435: \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u043d\u0430\u0431\u043e\u0440, \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u043f\u043e\u0440\u044f\u0434\u043e\u043a, \u043e\u0434\u0438\u043d seed;\n- \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u043e\u0446\u0435\u043d\u043a\u0438 PPL: \u043e\u0434\u0438\u043d \u0434\u0430\u0442\u0430\u0441\u0435\u0442, \u043e\u0434\u043d\u0430 \u0434\u043b\u0438\u043d\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438, \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u043d\u0430\u0431\u043e\u0440 \u0441\u044d\u043c\u043f\u043b\u043e\u0432, \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0441\u0435\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f;\n- \u0432\u0441\u0451 \u043f\u0440\u043e\u0447\u0435\u0435 \u0440\u0430\u043d\u0442\u0430\u0439\u043c-\u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u0435 (\u0435\u0441\u043b\u0438 \u0432\u0435\u0441\u0430 \u0442\u043e\u0436\u0435 \u043a\u0432\u0430\u043d\u0442\u0443\u044e\u0442\u0441\u044f \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e, \u0431\u0435\u0437 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433\u0430 \u043f\u043e \u0441\u0435\u0442\u043a\u0435, \u043b\u0438\u0431\u043e FP16 \u2014 \u043f\u043e \u0441\u0435\u0442\u0430\u043f\u0443 \u0438\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430).\n\n**\u0417\u0430\u0432\u0438\u0441\u0438\u043c\u0430\u044f \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u043e\u043f\u0442\u0438\u043c\u0443\u043c\u0430:** PPL (\u0434\u0435\u043b\u044c\u0442\u0430 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e FP16-\u0431\u0435\u0439\u0437\u043b\u0430\u0439\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u043c\u043e\u0434\u0435\u043b\u0438). \u041e\u043f\u0442\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 c* = argmin PPL \u043f\u043e \u0441\u0435\u0442\u043a\u0435 \u0434\u043b\u044f \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044f C; \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u043c A \u0438 B, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043d\u044f\u0442\u044c, \u0447\u044c\u044f \u043e\u0448\u0438\u0431\u043a\u0430 \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u0435\u0442. \u041f\u043b\u044e\u0441 \u043a\u0440\u0438\u0432\u0430\u044f PPL(c) \u2014 \u0432\u043e\u043f\u0440\u043e\u0441 \"\u043a\u0430\u043a \u0432\u043b\u0438\u044f\u0435\u0442\" \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0444\u043e\u0440\u043c\u043e\u0439 \u043a\u0440\u0438\u0432\u043e\u0439 (\u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u043e\u0441\u0442\u044c, \u043d\u0430\u043b\u0438\u0447\u0438\u0435/\u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430, \u043a\u0440\u0443\u0442\u0438\u0437\u043d\u0430).\n\n**\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438:**\n- FP16 \u0431\u0435\u0437 \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f \u2014 \u0431\u0430\u0437\u043e\u0432\u0430\u044f PPL;\n- c = 1.0 (\u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433 \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d) \u2014 \u0442\u043e\u0447\u043a\u0430 \u043e\u0442\u0441\u0447\u0451\u0442\u0430 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433\u0430;\n- \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044c: \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u0441 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u043c\u0438 \u0441\u0438\u0434\u0430\u043c\u0438 (\u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a) \u0438\u043b\u0438 \u0445\u043e\u0442\u044f \u0431\u044b \u043e\u0446\u0435\u043d\u043a\u0430 \u043d\u0430 \u043d\u0435\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u043e\u043a\u043d\u0430\u0445, \u0447\u0442\u043e\u0431\u044b \u0443\u0431\u0435\u0434\u0438\u0442\u044c\u0441\u044f, \u0447\u0442\u043e \u043e\u043f\u0442\u0438\u043c\u0443\u043c \u043d\u0435 \u0448\u0443\u043c;\n- \u0441\u0433\u043b\u0430\u0436\u0438\u0432\u0430\u043d\u0438\u0435: \u0435\u0441\u043b\u0438 PPL \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u043e \u043e\u043a\u043d\u0430\u043c \u2014 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043f\u043e \u043d\u0435\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u044e\u0449\u0438\u043c\u0441\u044f \u043e\u043a\u043d\u0430\u043c \u043e\u0434\u043d\u043e\u0439 \u0434\u043b\u0438\u043d\u044b.\n\n**\u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u0442\u043e\u0447\u043a\u0438:** \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e (\u043b\u043e\u043a\u0443\u0441, c): \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u043d\u0442\u0430\u0439\u043c \u2192 \u043f\u0440\u043e\u0433\u043e\u043d \u043e\u0446\u0435\u043d\u043a\u0438 \u2192 \u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c PPL, \u0394PPL vs FP16. \u0418\u0442\u043e\u0433 \u2014 \u0442\u0430\u0431\u043b\u0438\u0446\u0430 3\u00d710 + \u0434\u0432\u0435 \u043a\u0440\u0438\u0432\u044b\u0435 (A, B) \u0438 \u0441\u0432\u043e\u0434\u043d\u0430\u044f (C), \u0432\u044b\u0431\u043e\u0440 c*.\n\n## 3. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438\n\n\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0432\u0437\u044f\u0442\u044b \u043c\u043d\u043e\u044e \u043a\u0430\u043a \u0434\u0430\u043d\u043d\u043e\u0441\u0442\u044c, \u041d\u0415 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u044b \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u0430\u043c\u0438):\n1. Clipping ratio \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0434\u043e\u043b\u044f \u043e\u0442 max|tensor| (\u0438\u043b\u0438 \u043a\u0430\u043a \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f), \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u043c\u0430\u044f \u043f\u0440\u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f \u2014 \u0442\u043e\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0432 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u0430\u0445 \u043c\u043d\u0435 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e.\n2. \u0411\u0438\u0442\u043d\u043e\u0441\u0442\u0438: \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u044b; \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, INT8 \u0432\u0445\u043e\u0434\u044b / INT8 \u0438\u043b\u0438 INT4 KV) \u2014 \u043d\u043e \u044d\u0442\u043e \u043d\u0430\u0434\u043e \u0432\u0437\u044f\u0442\u044c \u0438\u0437 setup-\u0447\u0430\u043d\u043a\u043e\u0432.\n3. \u0414\u0430\u0442\u0430\u0441\u0435\u0442 PPL: \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d; \u0442\u0438\u043f\u0438\u0447\u043d\u044b\u0439 \u0432\u044b\u0431\u043e\u0440 \u0434\u043b\u044f LLAMA2-7B \u2014 WikiText-2, \u0434\u043b\u0438\u043d\u0430 2048 \u2014 \u043d\u043e \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435.\n4. \u041a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435: \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u044b (\u043a\u0430\u043a\u043e\u0439 \u043a\u043e\u0440\u043f\u0443\u0441, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u044d\u043c\u043f\u043b\u043e\u0432, \u043a\u0430\u043a\u0430\u044f \u0434\u043b\u0438\u043d\u0430) \u2014 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 PTQ-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b, \u043d\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043d\u0443\u0436\u043d\u043e \u043f\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0443.\n5. \u0413\u0440\u0430\u043d\u0443\u043b\u044f\u0440\u043d\u043e\u0441\u0442\u044c \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f (per-token/per-channel/per-group) \u2014 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0430.\n6. \u041a\u0432\u0430\u043d\u0442\u0443\u044e\u0442\u0441\u044f \u043b\u0438 \u0432\u0435\u0441\u0430 \u0438 \u0432 \u043a\u0430\u043a\u043e\u0439 \u0431\u0438\u0442\u043d\u043e\u0441\u0442\u0438 \u2014 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e; \u0434\u0438\u0437\u0430\u0439\u043d \u0434\u0435\u0440\u0436\u0438\u0442 \u044d\u0442\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u043e\u0439, \u043d\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b \u043d\u0443\u0436\u043d\u043e \u0438\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430.\n7. \"\u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 clipping ratio\" \u0442\u0440\u0430\u043a\u0442\u0443\u044e \u043a\u0430\u043a \u043e\u0434\u043d\u043e \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0435 c \u043d\u0430 \u0432\u0441\u044e \u0441\u0435\u0442\u044c/\u0432\u0441\u0435 \u0441\u043b\u043e\u0438 (\u043d\u0435 per-layer) \u2014 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e.\n\n\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0434\u0438\u0437\u0430\u0439\u043d \u043d\u0435 \u0441\u043d\u0438\u043c\u0430\u0435\u0442 \u0431\u0435\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430:\n- \u042f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043b\u0438 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433 \u0441\u0442\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c (\u043f\u043e\u0440\u043e\u0433 \u0438\u0437 \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0438) \u0438\u043b\u0438 \u0440\u0430\u043d\u0442\u0430\u0439\u043c-\u0434\u0438\u043d\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u043c (\u043f\u043e \u0442\u0435\u043a\u0443\u0449\u0435\u043c\u0443 \u0442\u0435\u043d\u0437\u043e\u0440\u0443) \u2014 \u0432\u043e\u043f\u0440\u043e\u0441 \u0441\u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d \u043a\u0430\u043a \"runtime quantization\", \u043d\u043e \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u043f\u043e\u0440\u043e\u0433\u0430 \u043d\u0435\u044f\u0441\u0435\u043d.\n- \u0415\u0441\u0442\u044c \u043b\u0438 \u0432 \u0441\u0435\u0442\u0430\u043f\u0435 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0442\u0440\u044e\u043a\u0438 (outlier-\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430, per-channel \u0434\u043b\u044f KV), \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043c\u0430\u0441\u043a\u0438\u0440\u0443\u044e\u0442 \u044d\u0444\u0444\u0435\u043a\u0442 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433\u0430.\n- \u0414\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u044f PPL \u043c\u0435\u0436\u0434\u0443 \u0441\u0438\u0434\u0430\u043c\u0438 \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0438 \u2014 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442, \u043d\u0443\u0436\u043d\u0430 \u043b\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044c \u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u0430 \u043b\u0438 \u0440\u0430\u0437\u043d\u0438\u0446\u0430 \u043c\u0435\u0436\u0434\u0443 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u043c\u0438 c.\n\n\u0427\u0435\u0433\u043e \u0432 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u0430\u0445 \u043d\u0435\u0442 (\u0438 \u044f \u043d\u0435 \u0432\u044b\u0434\u0443\u043c\u044b\u0432\u0430\u044e): \u0431\u0438\u0442\u043d\u043e\u0441\u0442\u0438, \u0434\u0430\u0442\u0430\u0441\u0435\u0442, seqlen, \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 c, \u0433\u0440\u0430\u043d\u0443\u043b\u044f\u0440\u043d\u043e\u0441\u0442\u044c, \u0441\u0442\u0430\u0442\u0443\u0441 \u0432\u0435\u0441\u043e\u0432. \u0412\u0441\u0451 \u044d\u0442\u043e \u2014 \u0432 \u0442\u0432\u043e\u0438\u0445 setup_1/10/17; \u043f\u0440\u0438\u0448\u043b\u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435, \u0438 \u044f \u0437\u0430\u043c\u0435\u043d\u044e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f 2\u20136 \u043d\u0430 \u0444\u0430\u043a\u0442\u044b \u0438 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u043a